**FeedContainer.jsx**
```jsx
import React, { useState, useEffect, useCallback, useRef } from 'react';
import { FeedProvider } from './FeedContext';
import VirtualScroller from './VirtualScroller';
import PostItem from './PostItem';
import LoadingSkeleton from './LoadingSkeleton';
import { useInfiniteQuery } from 'react-query';
import { useIntersectionObserver } from './hooks/useIntersectionObserver';

const FeedContainer = () => {
  const [posts, setPosts] = useState([]);
  const [hasNextPage, setHasNextPage] = useState(true);
  const loadMoreRef = useRef(null);
  const scrollPositionRef = useRef(0);

  const {
    data,
    fetchNextPage,
    hasNextPage: queryHasNextPage,
    isFetchingNextPage,
    isLoading,
    error
  } = useInfiniteQuery(
    'feed',
    ({ pageParam = null }) => fetchFeedPage(pageParam),
    {
      getNextPageParam: (lastPage) => lastPage.nextCursor,
      refetchOnWindowFocus: false,
      staleTime: 5 * 60 * 1000, // 5 minutes
    }
  );

  // Intersection Observer for infinite scroll
  useIntersectionObserver(
    loadMoreRef,
    () => {
      if (queryHasNextPage && !isFetchingNextPage) {
        fetchNextPage();
      }
    },
    { threshold: 0.1 }
  );

  useEffect(() => {
    if (data) {
      const allPosts = data.pages.flatMap(page => page.posts);
      setPosts(allPosts);
      setHasNextPage(queryHasNextPage);
    }
  }, [data, queryHasNextPage]);

  const handleScroll = useCallback((scrollTop) => {
    scrollPositionRef.current = scrollTop;
  }, []);

  const updatePost = useCallback((postId, updates) => {
    setPosts(prev => prev.map(post => 
      post.id === postId ? { ...post, ...updates } : post
    ));
  }, []);

  const removePost = useCallback((postId) => {
    setPosts(prev => prev.filter(post => post.id !== postId));
  }, []);

  if (isLoading) {
    return <LoadingSkeleton count={5} />;
  }

  if (error) {
    return <div className="feed-error">Failed to load feed</div>;
  }

  return (
    <FeedProvider value={{
      posts,
      updatePost,
      removePost,
      isLoading: isFetchingNextPage
    }}>
      <div className="feed-container">
        <VirtualScroller
          items={posts}
          itemHeight={400}
          onScroll={handleScroll}
          renderItem={({ item, index, style }) => (
            <div style={style} key={item.id}>
              <PostItem post={item} index={index} />
            </div>
          )}
        />

        {/* Load more trigger */}
        <div 
          ref={loadMoreRef} 
          className="load-more-trigger"
          style={{ height: '20px', margin: '20px 0' }}
        >
          {isFetchingNextPage && <LoadingSkeleton count={2} />}
          {!queryHasNextPage && posts.length > 0 && (
            <div className="end-of-feed">You've reached the end!</div>
          )}
        </div>
      </div>
    </FeedProvider>
  );
};

// API function
const fetchFeedPage = async (cursor) => {
  const response = await fetch(`/api/feed?cursor=${cursor || ''}&limit=10`);
  return response.json();
};

export default FeedContainer;
```

**VirtualScroller.jsx**
```jsx
import React, { useState, useEffect, useRef, useMemo } from 'react';

const VirtualScroller = ({ 
  items, 
  itemHeight, 
  containerHeight = window.innerHeight,
  overscan = 5,
  onScroll,
  renderItem 
}) => {
  const [scrollTop, setScrollTop] = useState(0);
  const [isScrolling, setIsScrolling] = useState(false);
  const scrollElementRef = useRef(null);
  const scrollTimeoutRef = useRef(null);

  const { visibleRange, totalHeight } = useMemo(() => {
    const containerTop = scrollTop;
    const containerBottom = containerTop + containerHeight;

    const startIndex = Math.max(0, Math.floor(containerTop / itemHeight) - overscan);
    const endIndex = Math.min(
      items.length - 1,
      Math.ceil(containerBottom / itemHeight) + overscan
    );

    return {
      visibleRange: { startIndex, endIndex },
      totalHeight: items.length * itemHeight
    };
  }, [scrollTop, containerHeight, itemHeight, items.length, overscan]);

  const visibleItems = useMemo(() => {
    const result = [];
    for (let i = visibleRange.startIndex; i <= visibleRange.endIndex; i++) {
      if (items[i]) {
        result.push({
          index: i,
          item: items[i],
          style: {
            position: 'absolute',
            top: i * itemHeight,
            width: '100%',
            height: itemHeight,
          }
        });
      }
    }
    return result;
  }, [visibleRange, items, itemHeight]);

  const handleScroll = (e) => {
    const newScrollTop = e.currentTarget.scrollTop;
    setScrollTop(newScrollTop);
    setIsScrolling(true);
    onScroll?.(newScrollTop);

    // Clear previous timeout
    if (scrollTimeoutRef.current) {
      clearTimeout(scrollTimeoutRef.current);
    }

    // Set scrolling to false after scroll ends
    scrollTimeoutRef.current = setTimeout(() => {
      setIsScrolling(false);
    }, 150);
  };

  return (
    <div
      ref={scrollElementRef}
      className="virtual-scroller"
      style={{
        height: containerHeight,
        overflow: 'auto',
        position: 'relative'
      }}
      onScroll={handleScroll}
    >
      <div
        className="virtual-scroller-content"
        style={{
          height: totalHeight,
          position: 'relative'
        }}
      >
        {visibleItems.map(({ index, item, style }) =>
          renderItem({ item, index, style })
        )}
      </div>
    </div>
  );
};

export default VirtualScroller;
```

**PostItem.jsx**
```jsx
import React, { useState, useContext, memo } from 'react';
import { FeedContext } from './FeedContext';
import PostHeader from './PostHeader';
import PostContent from './PostContent';
import PostMedia from './PostMedia';
import PostActions from './PostActions';
import CommentsSection from './CommentsSection';

const PostItem = memo(({ post, index }) => {
  const { updatePost } = useContext(FeedContext);
  const [showComments, setShowComments] = useState(false);
  const [isVisible, setIsVisible] = useState(false);

  const handleLike = async () => {
    const newLikeStatus = !post.isLiked;
    const newLikeCount = post.likeCount + (newLikeStatus ? 1 : -1);

    // Optimistic update
    updatePost(post.id, {
      isLiked: newLikeStatus,
      likeCount: newLikeCount
    });

    try {
      await fetch(`/api/posts/${post.id}/like`, {
        method: newLikeStatus ? 'POST' : 'DELETE'
      });
    } catch (error) {
      // Revert on error
      updatePost(post.id, {
        isLiked: !newLikeStatus,
        likeCount: post.likeCount
      });
    }
  };

  const handleShare = () => {
    if (navigator.share) {
      navigator.share({
        title: `Post by ${post.author.name}`,
        url: `/posts/${post.id}`
      });
    } else {
      navigator.clipboard.writeText(`${window.location.origin}/posts/${post.id}`);
    }
  };

  const handleComment = () => {
    setShowComments(!showComments);
  };

  return (
    <article className="post-item" data-post-id={post.id}>
      <PostHeader 
        author={post.author}
        timestamp={post.createdAt}
        isFollowing={post.author.isFollowing}
      />

      <PostContent 
        content={post.content}
        hashtags={post.hashtags}
        mentions={post.mentions}
      />

      {post.media && post.media.length > 0 && (
        <PostMedia 
          media={post.media}
          onVisibilityChange={setIsVisible}
        />
      )}

      <PostActions
        likeCount={post.likeCount}
        commentCount={post.commentCount}
        shareCount={post.shareCount}
        isLiked={post.isLiked}
        isBookmarked={post.isBookmarked}
        onLike={handleLike}
        onComment={handleComment}
        onShare={handleShare}
      />

      {showComments && (
        <CommentsSection
          postId={post.id}
          comments={post.comments}
          onCommentAdd={(comment) => {
            updatePost(post.id, {
              commentCount: post.commentCount + 1,
              comments: [...(post.comments || []), comment]
            });
          }}
        />
      )}
    </article>
  );
});

export default PostItem;
```

**Infinite Scroll Hook**
```jsx
// hooks/useInfiniteScroll.js
import { useEffect, useCallback, useRef } from 'react';

export const useInfiniteScroll = ({
  hasNextPage,
  fetchNextPage,
  isFetchingNextPage,
  threshold = 300
}) => {
  const sentinelRef = useRef(null);

  const handleIntersection = useCallback((entries) => {
    const [entry] = entries;
    if (entry.isIntersecting && hasNextPage && !isFetchingNextPage) {
      fetchNextPage();
    }
  }, [hasNextPage, fetchNextPage, isFetchingNextPage]);

  useEffect(() => {
    const sentinel = sentinelRef.current;
    if (!sentinel) return;

    const observer = new IntersectionObserver(handleIntersection, {
      rootMargin: `${threshold}px`,
      threshold: 0.1
    });

    observer.observe(sentinel);

    return () => {
      observer.unobserve(sentinel);
      observer.disconnect();
    };
  }, [handleIntersection, threshold]);

  return sentinelRef;
};

// hooks/useVirtualization.js
import { useMemo } from 'react';

export const useVirtualization = ({
  items,
  itemHeight,
  containerHeight,
  scrollTop,
  overscan = 5
}) => {
  return useMemo(() => {
    const startIndex = Math.max(
      0, 
      Math.floor(scrollTop / itemHeight) - overscan
    );

    const endIndex = Math.min(
      items.length - 1,
      Math.ceil((scrollTop + containerHeight) / itemHeight) + overscan
    );

    const visibleItems = [];
    for (let i = startIndex; i <= endIndex; i++) {
      if (items[i]) {
        visibleItems.push({
          index: i,
          data: items[i],
          offsetTop: i * itemHeight
        });
      }
    }

    return {
      startIndex,
      endIndex,
      visibleItems,
      totalHeight: items.length * itemHeight
    };
  }, [items, itemHeight, containerHeight, scrollTop, overscan]);
};

// Feed Performance Optimization
export const useFeedOptimization = () => {
  const preloadImages = useCallback((posts) => {
    posts.forEach(post => {
      if (post.media) {
        post.media.forEach(media => {
          if (media.type === 'image') {
            const img = new Image();
            img.src = media.thumbnailUrl || media.url;
          }
        });
      }
    });
  }, []);

  const lazyLoadMedia = useCallback((element, mediaSrc) => {
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          const img = entry.target;
          img.src = mediaSrc;
          img.onload = () => {
            img.classList.add('loaded');
          };
          observer.unobserve(img);
        }
      });
    });

    observer.observe(element);
    return () => observer.disconnect();
  }, []);

  return { preloadImages, lazyLoadMedia };
};
