        ST4[Accessibility<br/>Keyboard navigation]
    end

    UT1 --> IT1
    UT2 --> IT2
    UT3 --> IT3
    UT4 --> IT4

    IT1 --> E2E1
    IT2 --> E2E2
    IT3 --> E2E3
    IT4 --> E2E4

    E2E1 --> ST1
    E2E2 --> ST2
    E2E3 --> ST3
    E2E4 --> ST4
```

